import{_ as t,H as a,f as i,i as n}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"10 | 原生学习：Hermes与递归自我改进","description":"","frontmatter":{},"headers":[{"level":2,"title":"进化：前九讲我们做了什么","slug":"进化-前九讲我们做了什么","link":"#进化-前九讲我们做了什么","children":[]},{"level":2,"title":"自进化：把复盘从人手里接过来","slug":"自进化-把复盘从人手里接过来","link":"#自进化-把复盘从人手里接过来","children":[]},{"level":2,"title":"复利就是递归","slug":"复利就是递归","link":"#复利就是递归","children":[]},{"level":2,"title":"后半程从哪里开始？","slug":"后半程从哪里开始","link":"#后半程从哪里开始","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[{"level":3,"title":"观察题：先把 Hermes 用起来","slug":"观察题-先把-hermes-用起来","link":"#观察题-先把-hermes-用起来","children":[]},{"level":3,"title":"思考题：一次纠正，该放在哪一层？","slug":"思考题-一次纠正-该放在哪一层","link":"#思考题-一次纠正-该放在哪一层","children":[]}]}],"relativePath":"自进化Agent工程实战/10｜原生学习：Hermes与递归自我改进.md","filePath":"自进化Agent工程实战/10｜原生学习：Hermes与递归自我改进.md","lastUpdated":1795559729000}'),l={name:"自进化Agent工程实战/10｜原生学习：Hermes与递归自我改进.md"};function r(s,e,p,o,h,m){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="_10-原生学习-hermes与递归自我改进" tabindex="-1">10 | 原生学习：Hermes与递归自我改进 <a class="header-anchor" href="#_10-原生学习-hermes与递归自我改进" aria-label="Permalink to &quot;10 | 原生学习：Hermes与递归自我改进&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>上一讲我们讲了怎么拦住越界操作。但 Agent 下次再遇到类似问题，并不会自动记住今天发生过什么。接下来这一讲，我们就来看它怎么从自己的经历里长出本事。</p><h2 id="进化-前九讲我们做了什么" tabindex="-1">进化：前九讲我们做了什么 <a class="header-anchor" href="#进化-前九讲我们做了什么" aria-label="Permalink to &quot;进化：前九讲我们做了什么&quot;">​</a></h2><p>在展开后半程之前，我们先花一点时间，回头看看我们已经掌握的知识。</p><p>前面这九讲聚焦在讲清一个问题：什么是进化。一个系统能从自己的经历里变得更好，这就是进化。</p><p>我们最早聊的，是怎么让大模型在企业里真正把任务跑通。这里面最关键的一块是上下文。同样一个模型，给它带了哪些历史、挂了哪些工具、什么时候把外部资料取进来，答出来的东西差别很大。</p><p>学完前九讲，我们已经知道了任务来的时候，上下文到底该怎么组织。</p><p>上下文理清楚之后，我们讲了怎么让它真的动手。Agent 不是只会聊天，它得能调工具、能读文件、能查日志、能在系统里走流程。这中间我们拆了它一轮一轮是怎么转的：拿到任务、想下一步、调工具、看结果、再想下一步。到这儿，大模型就从&quot;能聊&quot;变成了&quot;能干活&quot;。</p><p>活能干了，下一个问题是怎么让它不用每次都从零开始。我们引入了 Memory 和 Skill。Memory 记的是事实：这个业务线有什么规矩、用户偏好怎么沟通、哪个系统的接口有什么坑。Skill 记的是方法：碰到某类问题，先查什么、再查什么、什么条件下走哪条分支。这两样东西你可以手写，也可以让它把一次干通的活自己总结成一份方法，下次直接调。到这儿，Agent 已经有了基本的执行能力和经验积累。</p><p>但光会干还不够，还得让它不乱干。所以花了一整讲的时间讲权限边界：哪些目录能写、网络能不能开、审批怎么临时放行。</p><p>走到这一步，前半程其实已经把一个能在企业里干活的 Agent 搭出来了。上下文有了，工具会用了，经验能存了，边界也守住了。</p><p>但你应该已经感觉到，这套系统还差一口气。它干过的活，存下来的 Memory 和 Skill，就放在那儿；下次遇到类似问题，它会不会真用上、用上了有没有变好、上次那条经验是不是已经过时了，没人回头看。</p><h2 id="自进化-把复盘从人手里接过来" tabindex="-1">自进化：把复盘从人手里接过来 <a class="header-anchor" href="#自进化-把复盘从人手里接过来" aria-label="Permalink to &quot;自进化：把复盘从人手里接过来&quot;">​</a></h2><p>过去这一步全靠人：任务结束后，得有人回头把记录看一遍，把该补的事实补进记忆，把能复用的做法整理成方法。可什么时候该整理、要检查哪些，只要没人惦记，这事就直接略过去了。更现实的是，一个人一天能盯几个 Session？线上一天成百上千次请求，靠人一条条翻根本看不过来，真正有价值的经验就藏在这些轨迹里。</p><p>自进化，就是把这件事从人手里接过来：系统自己从经历里学、自己改自己。这也是 Hermes这类 Harness 和早期 Agent 框架最大的区别：它从设计之初就把自进化当成核心能力，而不是事后补的插件。</p><p>Hermes 这边，每一次 Session 的完整记录都在，长期的 Memory 和 Skill 也有专门的管理。更关键的是后台复盘。任务结束之后，它会自己把刚才那段会话重看一遍，判断有没有值得留的事实、要不要调整方法，你不用每次纠正完再单独交代一句。这一步一旦自动化，线上那些成百上千次的轨迹就都有了去处。</p><p>存下来只是第一步。新任务有没有真用上，用上是不是少走弯路，会不会把一次偶然的成功当成能长期用的方法，都得靠后续任务一个个验证，因为写进去的东西也可能是片面的、过时的。</p><p>所以自我改进必须是个闭环：经验存下来，还要能在新任务上比较新旧方法，结果一旦变差，查得出是哪次改动带来的、退得回原来的版本。</p><h2 id="复利就是递归" tabindex="-1">复利就是递归 <a class="header-anchor" href="#复利就是递归" aria-label="Permalink to &quot;复利就是递归&quot;">​</a></h2><p>到这儿，我们说清楚了自进化是什么：系统自己从经历里学。那能不能更进一步？这一次改进，能不能在后面的改进里不断产生复利？前一次改进的结果，就这样参与了下一次改进。这就是我们说的递归，也就是递归自进化，RSI。</p><p>这种改变其实分三层，按改进对象区分，成本、反馈周期和验证方式都不一样。</p><p>最远的是第 3 层，靠训练改进模型。Agent 先跑出一批 rollout，就是它跑任务留下的完整轨迹。这些轨迹攒起来、筛过，拿去更新权重，得到下一代模型，再放回 Harness 当底座，接着跑新的任务。这条路要把经历转成训练数据，再经过训练、评测、部署一整套流程，改进才会体现在后续表现上，反馈链路很长。</p><p>近一点的是第 2 层。Harness 本身是代码，Code Agent 会写代码，于是可以直接改自己下一次运行依赖的那部分，下次启动就跑在改进后的自己身上。</p><p>这有点像编译器自举，早在 2023 年就有人沿着这条路探索，STOP 让调用模型的优化程序改进自己，而不重训底层模型。这层离产业落地比较远，自主修改 Harness 会影响后续任务的执行，需要更全面的回归测试和部署控制。</p><p>而离我们最近的是第 1 层：Agent 用自己的经历更新 Memory 和 Skill。三层里，对企业 Agent落地最见效的，恰恰是这一层。</p><p>Hermes 的官方表述是，Skill 就是它的程序记忆，Memory 就是陈述性记忆，两者一起构成自我改进循环。不光新事实、新方法会往里写，已经存着的那些，也会在后面用的时候被发现过时或不对，再被修正。而且这一层不用动模型权重，也不必先打通训练管线，每一条事实和方法都读得见、审得了、能版本化，将来换了底座模型，这套积累还在。对企业来说，这才是该优先落地的方向。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/10/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/10/1.png" alt=""></a></p><p>你会发现后半程大部分工作都发生在离线。</p><p>在线那一头，Agent 实时接任务、给结果，这部分大家用了一阵子已经比较熟了；但离线这一头，也就是任务结束之后后台干的那些事，相对陌生。这门课后半程主要补的就是这块。为了让陈述性记忆和程序记忆都能不断迭代，再从单实例的学习扩到一群实例共享经验，后面这些讲做的都是同一件事：把离线复盘这件事做扎实。</p><h2 id="后半程从哪里开始" tabindex="-1">后半程从哪里开始？ <a class="header-anchor" href="#后半程从哪里开始" aria-label="Permalink to &quot;后半程从哪里开始？&quot;">​</a></h2><p>一场日志调查已经结束，Agent 给了回答，你也没再提新要求。过了一会儿，聊天窗口却冒出来一行：</p><ul><li>Self-improvement review: Memory updated</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/10/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/10/2.png" alt=""></a></p><p>回答都发出去了，Hermes 为什么还在干活？</p><p>后台看到了什么？为什么这条日志入口值得留下，当晚另外的请求和日志却没留？新 Session又从什么时候开始用上这条 Memory？</p><p>我们就从这行提示说起。后半程要做的事分几步，最后用一个综合实践把所有部件装到一起。</p><p>第一步，拆开后台复盘和陈述性记忆。回答发出去、你没提新要求的时候，后台会在不打扰你的前提下，把刚才这段经历重看一遍，挑出后面还用得上的事实，而不是把这次的细节都留下。</p><p>复盘是独立线程跑、满足条件才触发，只尽力而为，不会拖慢你当下的任务。然后是陈述性记忆本身：一条过时的事实怎么被有依据地替换，前后改动都留痕，因为错误的记忆比没有记忆更糟。光靠记忆有时不够，有些细节得回到当时的会话里，把原始经过一条条取回来。</p><p>第二步，写进程序记忆，也就是 Skill。让工作方法也跟着经历更新。一次任务里走通的做法，Agent 能自己沉淀成一份新 Skill；遇到新条件，优先在原有方法上打补丁，而不是另起一份；攒多了，再把整个技能库梳理一遍，重复的合并、低频但有用的归档、真过时的搁置。</p><p>第三步，保证它不会越改越偏。每一次改动，先在一组固定用例上验真实效果。离线评估评测的是业务结果，不是它怎么做到的（连评分这套程序本身也要被测）。整库随时能存快照、回到任意一刻。离线调出来的新做法，离线分数再高，也得回到真实任务上跑过才算数。</p><p>第四步，把单个 Agent 的学习扩到多个实例。不同实例在各自工作里踩过、纠正过的地方，汇总起来提炼成共同方法，再分发到另一个 Agent 的 Context 里。它一加载就照着做，却不必知道这套方法是谁、在哪一次纠正的。经验到这一步，才从一个人的积累变成一群人的积累。</p><p>最后一步是总装。把在线运行、状态持久化和后台学习这几层闭环端到端跑通。再用一个不设标准答案的综合实践，让你从一次在线任务出发，自己走完任务执行、后台沉淀、跨实例共享，一直到版本采用和快照恢复。</p><p>这个顺序不是随便排的。先让单个 Agent 能从经历里学，再保证它不会越改越偏，然后才扩到一群 Agent。每一步都建立在前一步跑通、你能随时检查和回退的基础上。</p><p>走完这些，我们就有了一套真实跑通、持续把经验沉淀为企业资产的 Agent。配套代码放在了GitHub 仓库，随课程更新。每一讲都配了真实可跑的练习，你跟着跑一遍，就能看到属于你自己的结果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/10/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E8%BF%9B%E5%8C%96Agent%E5%B7%A5%E7%A8%8B%E5%AE%9E%E6%88%98/images/10/3.png" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>学到这里，我们做个总结吧。</p><p>前九讲我们把一个能在企业里干活的 Agent 搭出来了：上下文、工具、Memory、Skill、权限边界，一应俱全，但任务之间的经验闭环还没合上。</p><p>这一讲我们把这头接上：自进化不是一次性总结，而是在线跑任务、离线复盘改进这样一个不断转的循环。RSI 分三层，企业最先该把力气花在 Memory 和 Skill 这层，后面所有内容，都在给这个循环加零件。</p><p>接下来我们就从回答收尾后那行 Memory updated 说起，看这次复盘具体怎么发生、又留下了什么。</p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><h3 id="观察题-先把-hermes-用起来" tabindex="-1">观察题：先把 Hermes 用起来 <a class="header-anchor" href="#观察题-先把-hermes-用起来" aria-label="Permalink to &quot;观察题：先把 Hermes 用起来&quot;">​</a></h3><p>在自己的机器上装好 Hermes，挑一件你平时真要做的小事，让它独立跑一遍。别盯着它一步步操作，就按你自己的习惯把活交代下去，看它自己怎么推进、卡在哪、最后做成什么样。跑完之后翻一翻，它这次留下了什么 Memory，又写出了什么 Skill。下次再开一个新会话，问它跟上次那件事相关的问题，看它有没有自己翻出上次留下的东西。</p><h3 id="思考题-一次纠正-该放在哪一层" tabindex="-1">思考题：一次纠正，该放在哪一层？ <a class="header-anchor" href="#思考题-一次纠正-该放在哪一层" aria-label="Permalink to &quot;思考题：一次纠正，该放在哪一层？&quot;">​</a></h3><p>你在自己的业务里用 Hermes。有一次它查一个支付状态查错了，你当场纠正了一句。现在要判断这句纠正该沉淀到哪一层。</p><p>如果它只是记错了一个事实（这个渠道早就停了），该写进哪一层？如果它这次是步骤走错了，以后碰到同类问题按这个新步骤来就行，又该写进哪一层？还是说，你觉得这次纠正应该去训练模型？分别说说你的理由。</p><p>期待你在留言区积极发言，分享见解。如果这一讲对你有启发，欢迎分享给身边更多朋友。</p>',58)])])}const u=t(l,[["render",r]]);export{A as __pageData,u as default};
